CREATE TABLE IF NOT EXISTS device_registry (store TEXT NOT NULL,id TEXT NOT NULL,role TEXT NOT NULL,label TEXT NOT NULL,created INTEGER NOT NULL,seen INTEGER NOT NULL,expires INTEGER NOT NULL,revoked INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(store,id));
CREATE TABLE IF NOT EXISTS pairing_codes (store TEXT NOT NULL,role TEXT NOT NULL,hash TEXT NOT NULL,updated INTEGER NOT NULL,PRIMARY KEY(store,role));
ALTER TABLE product_prices ADD COLUMN sold_out INTEGER NOT NULL DEFAULT 0;
